def transform(grid):
    bg = 0
    active_rows = [r for r in range(len(grid)) if any(grid[r][c] != bg for c in range(len(grid[0])))]
    if not active_rows:
        return [[bg] * 9 for _ in range(5)]

    # Find global min/max cols
    min_col = min(c for r in active_rows for c in range(len(grid[r])) if grid[r][c] != bg)
    max_col = max(c for r in active_rows for c in range(len(grid[r])) if grid[r][c] != bg)

    width = 9

    # Process each active row and create output row
    output = []
    for r in active_rows:
        row_vals = []
        row_data = grid[r]

        for c in range(min_col, max_col + 1):
            if row_data[c] != bg:
                row_vals.append((c, row_data[c]))

        # Build output row (width=9, center/scale content)
        row_out = [bg] * width

        if row_vals:
            # Map first and last non-bg to edges
            first_c = row_vals[0][0]
            last_c = row_vals[-1][0]

            # Linear mapping from [first_c, last_c] to [0, 8]
            span = last_c - first_c
            for c, val in row_vals:
                if span > 0:
                    ratio = (c - first_c) / span
                else:
                    ratio = 0.5
                target = int(round(ratio * (width - 1)))
                if 0 <= target < width:
                    # Don't overwrite if there's an edge marker
                    if target == 0 or target == width - 1:
                        if row_vals.index((c, val)) == 0:  # First pixel -> col 0
                            row_out[0] = val
                        elif row_vals.index((c, val)) == len(row_vals) - 1:  # Last
                            row_out[8] = val
                        else:
                            row_out[target] = val
                    else:
                        row_out[target] = val
                else:
                    target = 0
                    row_out[target] = val

        output.append(row_out)

    return output
